<?php require_once __DIR__ . '/includes/config.php';role(['admin']);$p=db();$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){check();if(strlen($_POST['password'])<8)$msg='Password must be at least 8 characters';else{$s=$p->prepare('INSERT INTO users(full_name,username,password_hash,role) VALUES(?,?,?,?)');try{$s->execute([$_POST['full_name'],$_POST['username'],password_hash($_POST['password'],PASSWORD_DEFAULT),$_POST['role']]);log_action('CREATE_USER',$_POST['username']);$msg='User created';}catch(Throwable $e){$msg='Username already exists';}}}$rows=$p->query('SELECT full_name,username,role FROM users')->fetchAll();head('Users');?><h1>User management</h1><div class="panel"><p><?=e($msg)?></p><form method="post" class="grid"><input type="hidden" name="token" value="<?=e(token())?>"><label>Full name<input name="full_name" required></label><label>Username<input name="username" required></label><label>Password<input name="password" type="password" minlength="8" required></label><label>Role<select name="role"><option value="hr">HR</option><option value="payroll">Payroll</option><option value="auditor">Auditor</option><option value="admin">Admin</option></select></label><button>Create user</button></form></div><div class="panel table"><table><tr><th>Name</th><th>Username</th><th>Role</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['full_name'])?></td><td><?=e($r['username'])?></td><td><?=e($r['role'])?></td></tr><?php endforeach;?></table></div><?php foot();?>